"""Read-only benchmark review: preserve failures and separate mechanics from science."""
import argparse
import collections
import html
import json
from pathlib import Path


def main():
    parser=argparse.ArgumentParser();parser.add_argument('campaign');args=parser.parse_args();root=Path(args.campaign)
    catalog=json.loads((root/'catalog.json').read_text());data=[]
    states={mode:json.loads((root/(mode+'-status.json')).read_text()) if (root/(mode+'-status.json')).exists() else {} for mode in ['oracle','model']}
    source_review=json.loads((root/'source-review.json').read_text()) if (root/'source-review.json').exists() else {'warnings':[]}
    for case in catalog:
        row={k:case[k] for k in ['id','category','project','scenario','request','expectation']}
        row['oracle_reason']=case.get('oracle_reason')
        row['source_warnings']=[w for w in source_review['warnings'] if w['project']==case['project']]
        row['figure']='figures/'+case['id']+'.png' if (root/'figures'/(case['id']+'.png')).is_file() else None
        for mode in states:
            value=states[mode].get('results',{}).get(case['id'],{})
            current=value.get('source_sha256')==states[mode].get('current_code')
            row[mode]={k:value.get(k) for k in ['status','error','elapsed_seconds','planning','scientific_warnings','checks','source_sha256','case_sha256']}
            row[mode]['current']=current
            directory=value.get('artifact_directory')
            if directory:
                try:
                    d=Path(directory).relative_to(root).as_posix()
                    row[mode]['links']={name:d+'/'+name for name in ['planning.json','planning-error.json','plan.json','result.json','refined.gpx','refined.execution.json','native.log'] if (root/d/name).is_file()}
                except ValueError:pass
        data.append(row)
    follow=root/'follow-up-v5'
    follow_state=json.loads((follow/'model-status.json').read_text()) if (follow/'model-status.json').exists() else {}
    selection=json.loads((follow/'selection.json').read_text()) if (follow/'selection.json').exists() else {'cases':[]}
    for row in data:
        value=follow_state.get('results',{}).get(row['id'])
        if not value:continue
        value=dict(value);directory=Path(value['artifact_directory'])
        value['links']={name:(directory/name).relative_to(root).as_posix() for name in ['planning.json','planning-error.json','plan.json','result.json','refined.gpx','refined.execution.json','native.log'] if (directory/name).is_file()}
        row['follow_up']=value
    report={'source_warnings':source_review['warnings'],'follow_up':{'selected':selection['cases'],'counts':dict(collections.Counter(r['status'] for r in follow_state.get('results',{}).values()))},'cases':data,'denominator':100,'executable':sum(c['expectation']=='execute' for c in catalog),'needs_input':sum(c['expectation']=='needs_input' for c in catalog),'counts':{mode:dict(collections.Counter(x[mode].get('status') or 'pending' for x in data if x[mode]['current'])) for mode in states},'code':{mode:states[mode].get('current_code') for mode in states}}
    (root/'review-data.json').write_text(json.dumps(report,indent=2)+'\n')
    text='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RADAR-PD · Recipe validation</title>
<style>:root{font:15px system-ui;color:#16372e;background:#f4f7f5}body{margin:0}main{max-width:1400px;margin:auto;padding:28px}h1{font-size:28px;margin:8px 0}h2{font-size:20px}.card{background:white;border:1px solid #d4e0d9;border-radius:8px;padding:22px;margin:18px 0}.muted{color:#60756a;line-height:1.6}.stats{display:flex;gap:14px;flex-wrap:wrap}.stat{flex:1;min-width:160px;background:#edf4ef;padding:16px;border-radius:6px}.stat b{display:block;font-size:27px}.controls{display:flex;gap:12px;margin:20px 0}input,select,button{font:inherit;padding:8px;border:1px solid #a8bfb0;border-radius:4px;background:white}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:12px;text-align:left;border-bottom:1px solid #dce5df;vertical-align:top}tr[data-id]{cursor:pointer}tr[data-id]:hover{background:#f0f6f2}.scroll{overflow:auto}.badge{display:inline-block;padding:4px 7px;border-radius:4px;background:#e8edf0;color:#3f5260}.verified_execution,.correctly_blocked{background:#e1f2e7;color:#1d5c36}.scientific_stop{background:#fff0d6;color:#875917}.semantic_mismatch,.runtime_defect,.planner_validation_failure,.provider_blocked{background:#ffe9e5;color:#9b3f2a}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace;background:#f5f7f6;padding:15px;max-height:650px;overflow:auto}a{color:#216443}dialog{width:min(1150px,90vw);max-height:90vh;border:1px solid #aec4b7;border-radius:8px;padding:24px}dialog::backdrop{background:#102c2466}.links{display:flex;gap:15px;flex-wrap:wrap}.close{float:right}img{max-width:100%;height:auto}summary{cursor:pointer;padding:10px 0}.note{padding:14px;border-left:3px solid #b68b3d;background:#fff7e9;line-height:1.6}</style>
<main><p class="muted">RADAR-PD · GPX REFINEMENT RECIPES</p><h1>100-case validation review</h1><p class="muted">Luna · reasoning none · independent recipe oracles · compiled GSAS-II execution in Linux/amd64. No Studio application or Python environment is used.</p>
<div class="card"><div class="stats" id="stats"></div><p class="note"><b>Execution verification is not scientific acceptance.</b> A scientific stop means refinement reached a bound, lost identifiability or failed another scientific check; it is not a completed result. Clarification cases must not reach the solver. Some source GPXs have poor preliminary fits; this campaign tests whether requested operations are performed accurately, not whether every structural model is correct.</p><p class="note" id="sourcewarn" hidden></p><details><summary>What is checked</summary><p class="muted">Independent checks compare the full requested active sets, stage order, cycles, bounds, exclusions, texture and occupancy equations with the model plan. Native checks inspect actual flags and covariance variables, verify fixed values and instrument calibration, preserve observed data and source GPXs, and check physical relations. Earlier failures and code versions remain in the campaign artifacts.</p><p class="muted">Limits: site-capacity detection uses exact co-located sites; alternate symmetry representatives and split-site models still need explicit scientific relations. Magnetic models, anisotropic ADP changes, new atoms/phases and arbitrary Python are not supported. OSS 120B remains the deployment target and has not been validated by these Luna tests.</p></details></div>
<div class="card" id="followup"></div><div class="card"><div class="controls"><input id="search" placeholder="Search recipe, sample or case" aria-label="Search cases"><select id="category" aria-label="Recipe category"><option value="">All categories</option></select><select id="status" aria-label="Model outcome"><option value="">All outcomes</option><option>verified_execution</option><option>scientific_stop</option><option>correctly_blocked</option><option>semantic_mismatch</option><option>runtime_defect</option><option>planner_validation_failure</option><option>provider_blocked</option><option>pending</option></select><button onclick="load()">Refresh</button></div><div class="scroll"><table><thead><tr><th>Case</th><th>Requested course</th><th>GPX</th><th>Native reference</th><th>Full 100-case run</th><th>Calls</th><th>Targeted follow-up</th></tr></thead><tbody id="rows"></tbody></table></div></div><p class="muted">Select a row to inspect its exact request, plan, stage receipts and downloadable GPX. Full data: <a href="review-data.json">review JSON</a> · <a href="catalog.json">all 100 recipes</a> · <a href="input-seal.json">sealed input hashes</a> · <a href="model-status-v3-complete.json">previous full model run</a></p></main>
<dialog id="detail"><button class="close" onclick="this.parentNode.close()">Close</button><h2 id="title"></h2><p id="description" class="muted"></p><h3>Exact request</h3><pre id="request"></pre><p id="error" class="note" hidden></p><div class="links" id="links"></div><details open><summary>Proposed model plan</summary><pre id="plan"></pre></details><details><summary>Independent execution audit</summary><pre id="audit"></pre></details><div id="figure"></div></dialog>
<script>
let data={cases:[]};const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=s=>String(s||'pending').replaceAll('_',' ');const badge=s=>`<span class="badge ${esc(s||'pending')}">${esc(label(s))}</span>`;
async function load(){const r=await fetch('review-data.json');data=await r.json();const categories=[...new Set(data.cases.map(c=>c.category))];if($('category').options.length===1)$('category').innerHTML+=[...categories].map(c=>`<option>${esc(c)}</option>`).join('');render();}
function render(){const counts=data.counts?.model||{};$('sourcewarn').hidden=!data.source_warnings.length;$('sourcewarn').textContent=data.source_warnings.map(w=>w.project+': label '+w.label_claim+'; stored symmetry '+w.stored_space_group+'. '+w.consequence).join(' ');$('stats').innerHTML=[[100,'Recipe cases'],[data.executable,'Intended execution'],[data.needs_input,'Require clarification'],[counts.verified_execution||0,'Verified executions'],[counts.scientific_stop||0,'Scientific stops'],[counts.correctly_blocked||0,'Correctly blocked'],[counts.semantic_mismatch||0,'Intent errors · blocked'],[(counts.planner_validation_failure||0)+(counts.provider_blocked||0),'Planner/provider errors']].map(([n,t])=>`<div class="stat"><b>${n}</b>${esc(t)}</div>`).join('');$('followup').innerHTML='<h2>Targeted regression after the full run</h2><p class="muted">'+data.follow_up.selected.length+' selected cases · '+Object.entries(data.follow_up.counts).map(([s,n])=>n+' '+esc(label(s))).join(' · ')+'. These results do not overwrite the full run. Its one planner-validation failure was an HTTPS timeout during repair, rather than an invalid completed reply.</p><p class="muted">Native reference: '+Object.entries(data.counts.oracle).map(([s,n])=>n+' '+esc(label(s))).join(' · ')+'. <a href="saved-gpx-post-audit.json">Independent saved-GPX audit</a> · <a href="input-preservation.json">Original/input preservation</a></p>';let text=$('search').value.toLowerCase();$('rows').innerHTML=data.cases.filter(c=>(!$('category').value||c.category===$('category').value)&&(!$('status').value||(c.model.current?c.model.status:'pending')===$('status').value)&&(!text||JSON.stringify(c).toLowerCase().includes(text))).map(c=>`<tr data-id="${c.id}"><td>${c.id}</td><td><b>${esc(c.scenario)}</b><br>${esc(label(c.category))}</td><td>${esc(c.project)}</td><td>${c.expectation==='needs_input'?'Not run · clarification':badge(c.oracle.current?c.oracle.status:'pending')}</td><td>${badge(c.model.current?c.model.status:'pending')}</td><td>${c.model.planning?.calls??'—'}</td><td>${c.follow_up?'<button data-follow="'+c.id+'">'+esc(label(c.follow_up.status))+'</button>':'—'}</td></tr>`).join('');document.querySelectorAll('tr[data-id]').forEach(row=>row.onclick=()=>show(row.dataset.id));document.querySelectorAll('button[data-follow]').forEach(button=>button.onclick=e=>{e.stopPropagation();show(button.dataset.follow,true)});}
async function show(id,follow=false){let c=data.cases.find(x=>x.id===id);if(follow)c={...c,model:c.follow_up};$('title').textContent=id+' · '+c.scenario+(follow?' · targeted follow-up':' · full run');$('description').textContent=c.project+' · '+label(c.model.status);$('request').textContent=c.request;const issues=[c.model.error,c.oracle_reason,...(c.source_warnings||[]).map(w=>w.consequence)].filter(Boolean);$('error').hidden=!issues.length;$('error').textContent=issues.join(' · ');let links=c.model.links||{};$('links').innerHTML=Object.entries(links).map(([n,p])=>`<a href="${esc(p)}">${esc(n)}</a>`).join('');$('plan').textContent='No accepted model plan';$('audit').textContent=JSON.stringify(c.model,null,2);$('figure').innerHTML='';$('detail').showModal();if(links['plan.json']){const r=await fetch(links['plan.json']);$('plan').textContent=JSON.stringify(await r.json(),null,2)}else if(links['planning.json']){const r=await fetch(links['planning.json']);const p=await r.json();$('plan').textContent=JSON.stringify(p.plan,null,2)}if(links['result.json']){const r=await fetch(links['result.json']);$('audit').textContent=JSON.stringify(await r.json(),null,2)}if(c.figure&&!follow)$('figure').innerHTML='<h3>Final fit in the refined range</h3><img alt="Native GSAS-II observed and calculated pattern" src="'+esc(c.figure)+'">'}
for(const id of ['search','category','status'])$(id).addEventListener(id==='search'?'input':'change',render);load();
</script></html>'''
    (root/'validation-report.html').write_text(text)
    print(json.dumps({'cases':len(data),'model_counts':report['counts']['model']}))


if __name__=='__main__':main()
